\u0924\u094d\u0924\u093e\u0913\u0902 \u0915\u093e \u0905\u0928\u0941\u092e\u093e\u0928 \u0939\u0948 \u0915\u093f \u0924\u093e\u092e\u093f\u0932 \u091c\u093e\u0924\u093f \u0906\u0930\u094d\u092f\u094b\u0902 \u0915\u0947 \u0938\u0902\u0938\u0930\u094d\u0917 \u0915\u0947 \u092a\u0942\u0930\u094d\u0935 \u0939\u0940 \u092c\u0939\u0941\u0924 \u0915\u0941\u091b \u0938\u092d\u094d\u092f\u0924\u093e \u092a\u094d\u0930\u093e\u092a\u094d\u0924 \u0915\u0930 \u091a\u0941\u0915\u0940 \u0925\u0940\u0964 \u0924\u093e\u092e\u093f\u0932 \u0932\u094b\u0917\u094b\u0902 \u0915\u0947 \u0930\u093e\u091c\u093e \u0939\u094b\u0924\u0947 \u0925\u0947 \u091c\u094b \u0915\u093f\u0932\u0947 \u092c\u0928\u093e\u0915\u0930 \u0930\u0939\u0924\u0947 \u0925\u0947\u0964 \u0935\u0947 \u0939\u091c\u093e\u0930 \u0924\u0915 \u0917\u093f\u0928 \u0932\u0947\u0924\u0947 \u0925\u0947\u0964 \u0935\u0947 \u0928\u093e\u0935, \u091b\u094b\u091f\u0947 \u092e\u094b\u091f\u0947 \u091c\u0939\u093e\u091c, \u0927\u0928\u0941\u0937, \u092c\u093e\u0923, \u0924\u0932\u0935\u093e\u0930 \u0907\u0924\u094d\u092f\u093e\u0926\u093f \u092c\u0928\u093e \u0932 \u30c7\u30fc\u30bf\u90e8\u306f\u5b9f\u884c\u3055\u308c\u306a\u3044\u90e8\u5206\u3067\u3042\u308b\u3002\u30d7\u30ed\u30b0\u30e9\u30e0\u3067\u4f7f\u7528\u3059\u308b\u30c7\u30fc\u30bf\u306e\u3046\u3061\u524d\u8ff0\u306e\u30a4\u30df\u30c7\u30a3\u30a8\u30a4\u30c8\u5024\u306b\u53ce\u307e\u3089\u306a\u3044\u3082\u306e\u3001\u6587\u5b57\u5217\u30ea\u30c6\u30e9\u30eb\u306a\u3069\u306e\u3088\u3046\u306a\u5b9a\u6570\u30c7\u30fc\u30bf\u3001\u30b0\u30ed\u30fc\u30d0\u30eb\u5909\u6570\uff08\u6a5f\u68b0\u8a9e\u3084\u30a2\u30bb\u30f3\u30d6\u30ea\u8a00\u8a9e\u30d7\u30ed\u30b0\u30e9\u30df\u30f3\u30b0\u306e\u7528\u8a9e\u3067\u306f\u30ef\u30fc\u30af\u30a8\u30ea\u30a2\uff09\u306e\u305f\u3081\u306e\u30d2\u30fc\u30d7\u9818\u57df\u3084\u30ed\u30fc\u30ab\u30eb\u5909\u6570\u306e\u305f\u3081\u306e\u30b9\u30bf\u30c3\u30af\u9818\u57df\u306a\u3069\u3002\u901a\u5e38\u3042\u308b\u7a0b\u5ea6\u307e\u3068\u3081\u3066\u7f6e\u304b\u308c\u308b\u3002\u901a\u4f8b\u3001\u547d\u4ee4\u3068\u3057\u3066\u89e3\u91c8\u3059\u308b\u3053\u3068\u306f\u3067\u304d\u306a\u3044\u304c\u3001\u5f37\u5236\u7684\u306b\u30c7\u30fc\u30bf\u90e8\u306b\u30b8\u30e3\u30f3\u30d7\u3055\u305b\u3001\u547d\u4ee4\u90e8\u3068\u3057\u3066\u89e3\u91c8\u3055\u305b\u308b\u3053\u3068\u3067\u3001\u4eee\u306b\u30c7\u30fc\u30bf\u90e8\u306b\u6a5f\u68b0\u8a9e\u76f8\u5f53\u306e\u547d\u4ee4\u30c7\u30fc\u30bf\u304c\u914d\u7f6e\u3055\u308c\u3066\u3044\u305f\u5834\u5408\u306f\u305d\u308c\u3089\u3092\u5b9f\u884c\u3059\u308b\u3053\u3068\u304c\u3067\u304d\u308b\u74b0\u5883\u3082\u5b58\u5728\u3059\u308b\u3002\u3053\u308c\u3092\u60aa\u7528\u3057\u3066\u3001\u30ea\u30bf\u30fc\u30f3\u30a2\u30c9\u30ec\u30b9\u306e\u66f8\u304d\u63db\u3048\u306a\u3069\u306b\u3088\u308a\u4e0d\u6b63\u306a\u30b3\u30fc\u30c9\u3092\u5b9f\u884c\u3055\u305b\u3066\u3057\u307e\u3046\u3088\u3046\u306a\u60aa\u610f\u306e\u3042\u308b\u30bd\u30d5\u30c8\u30a6\u30a7\u30a2\u304b\u3089\u30b3\u30f3\u30d4\u30e5\u30fc\u30bf\u3092\u4fdd\u8b77\u3059\u308b\u305f\u3081\u3001\u30c7\u30fc\u30bf\u5b9f\u884c\u9632\u6b62\uff08DEP\uff09\u3068\u547c\u3070\u308c\u308b\u6a5f\u80fd\u3092\u5099\u3048\u3066\u3044\u308b\u74b0\u5883\u3082\u3042\u308b\u3002 \u4ee5\u4e0a\u306e\u5404\u90e8\u5206\u306b\u5177\u4f53\u7684\u306b\u4f55\u30d3\u30c3\u30c8\u305a\u3064\u5272\u308a\u632f\u3063\u3066\u3001\u3069\u3046\u3044\u3046\u9806\u756a\u306b\u4e26\u3079\u308b\u304b\u3001\u3068\u3044\u3046\u5f62\u5f0f\uff08\u30d5\u30a9\u30fc\u30de\u30c3\u30c8\uff09\u306e\u3053\u3068\u3092\u6a5f\u68b0\u8a9e\u30d5\u30a9\u30fc\u30de\u30c3\u30c8\u306a\u3069\u3068\u8a00\u3046\u3002\u30a2\u30fc\u30ad\u30c6\u30af\u30c1\u30e3\u306b\u3088\u308a\u6a5f\u68b0\u8a9e\u30d5\u30a9\u30fc\u30de\u30c3\u30c8\u306f\u307e\u3061\u307e\u3061\u3060\u304c\u30011\u547d\u4ee4\u3092\u69cb\u6210\u3059\u308b\u30c7\u30fc\u30bf\u9577\u304c\u56fa\u5b9a\u306e\u300c\u56fa\u5b9a\u9577\u300d\u5f0f\u3068\u3001\u547d\u4ee4\u3084\u30aa\u30da\u30e9\u30f3\u30c9\u306e\u7a2e\u985e\u306b\u3088\u308a\u5909\u5316\u3059\u308b\u300c\u53ef\u5909\u9577\u300d\u5f0f\u306b\u5927\u5225\u3055\u308c\u308b\u3002\u53ef\u5909\u9577\u306e\u5834\u5408\u3001\u6a5f\u68b0\u8a9e\u547d\u4ee4\u306e\u7a2e\u985e\u306b\u3088\u3063\u3066\u30a2\u30c9\u30ec\u30b9\u90e8\u3084\u30c7\u30fc\u30bf\u90e8\u3001\u305d\u3057\u3066\u4e2d\u306b\u306f\u547d\u4ee4\u90e8\u307e\u3067\u3082\u9577\u3055\u304c\u5909\u308f\u308b\u3002\u3053\u306e\u305f\u3081\u3001\u8aad\u307f\u8fbc\u307f\u4f4d\u7f6e\u304c1\u30d0\u30a4\u30c8\u305a\u308c\u308c\u3070\u6a5f\u68b0\u8a9e\u306e\u547d\u4ee4\u306f\u305d\u308c\u4ee5\u964d\u306e\u3059\u3079\u3066\u306e\u547d\u4ee4\u304c\u6b63\u3057\u304f\u8aad\u307f\u8fbc\u307e\u308c\u305a\u610f\u5473\u3092\u5931\u3046\u305f\u3081\u3001\u305d\u3046\u3044\u3063\u305f\u6a5f\u68b0\u8a9e\u30d5\u30a9\u30fc\u30de\u30c3\u30c8\u306e\u30d0\u30a4\u30ca\u30ea\u3092\u5bfe\u8c61\u3068\u3059\u308b\u9006\u30a2\u30bb\u30f3\u30d6\u30e9\u306f\u5de5\u592b\u3092\u8981\u3059\u308b\u3002\u307e\u305f\u30e1\u30e2\u30ea\u304c\u9650\u3089\u308c\u308b\u30b7\u30b9\u30c6\u30e0\u3067\u306f\u672c\u6765\u306e\u547d\u4ee4\u306e\u9014\u4e2d\u306b\u98db\u3073\u8fbc\u307f\u5225\u306e\u610f\u5473\u306b\u4f7f\u3046\u3068\u3044\u3046\u30c8\u30ea\u30c3\u30af\u7684\u306a\u624b\u6cd5\u3082\u3042\u308b\u3002 \u306a\u304a\u4eba\u304c\u81ea\u5206\u306e\u773c\u3068\u982d\u8133\u3068\u624b\u3092\u4f7f\u3063\u3066\u30a2\u30bb\u30f3\u30d6\u30eb\u306e\u4f5c\u696d\u3092\u884c\u3046\u3053\u3068\u3092\u30cf\u30f3\u30c9\u30a2\u30bb\u30f3\u30d6\u30eb\u3068\u3044\u3046\u3002\u30b3\u30f3\u30d4\u30e5\u30fc\u30bf\u306e\u9ece\u660e\u671f\u306b\u306f\u3057\u3070\u3057\u3070\u30cf\u30f3\u30c9\u30a2\u30bb\u30f3\u30d6\u30eb\u304c\u884c\u308f\u308c\u3066\u3044\u305f\u304c\u3001\u8fd1\u5e74\u3067\u306f\u307b\u307c\u5168\u304f\u884c\u308f\u308c\u3066\u3044\u306a\u3044\u3002\u30d7\u30ed\u30bb\u30c3\u30b5\u304c4\u30d3\u30c3\u30c8\u30848\u30d3\u30c3\u30c8\uff082\u9032\u6570\u30674\u6841\u30848\u6841\uff09\u306e\u6642\u4ee3\u306a\u3089\u3070\u3001\u3084\u308d\u3046\u3068\u3059\u308c\u3070\u30cf\u30f3\u30c9\u30a2\u30bb\u30f3\u30d6\u30eb\u3082\u3067\u304d\u305f\u304c\u3001\u305d\u306e\u5f8cCPU\u306f16\u30d3\u30c3\u30c8\u300132\u30d3\u30c3\u30c8\u300164\u30d3\u30c3\u30c8\u3068\u306a\u308a\u300116\u30d3\u30c3\u30c8\u4ee5\u964d\u306f\u4eba\u9593\u306e\u982d\u8133\u3084\u624b\u306e\u80fd\u529b\u3067\u306f\u6271\u3044\u304d\u308c\u306a\u304f\u306a\u3063\u305f\u3002 \u0645\u062d\u0645\u0648\u062f \u062f\u0631\u0648\u064a\u0634 (13 \u0645\u0627\u0631\u0633 1941 \u2013 9 \u0623\u063a\u0633\u0637\u0633 2008)\u060c \u0623\u062d\u062f \u0623\u0647\u0645 \u0627\u0644\u0634\u0639\u0631\u0627\u0621 \u0627\u0644\u0641\u0644\u0633\u0637\u064a\u0646\u064a\u064a\u0646 \u0648\u0627\u0644\u0639\u0631\u0628 \u0627\u0644\u0630\u064a\u0646 \u0627\u0631\u062a\u0628\u0637 \u0627\u0633\u0645\u0647\u0645 \u0628\u0634\u0639\u0631 \u0627\u0644\u062b\u0648\u0631\u0629 \u0648\u0627\u0644\u0648\u0637\u0646. \u064a\u0639\u062a\u0628\u0631 \u062f\u0631\u0648\u064a\u0634 \u0623\u062d\u062f \u0623\u0628\u0631\u0632 \u0645\u0646 \u0633\u0627\u0647\u0645 \u0628\u062a\u0637\u0648\u064a\u0631 \u0627\u0644\u0634\u0639\u0631 \u0627\u0644\u0639\u0631\u0628\u064a \u0627\u0644\u062d\u062f\u064a\u062b \u0648\u0625\u062f\u062e\u0627\u0644 \u0627\u0644\u0631\u0645\u0632\u064a\u0629 \u0641\u064a\u0647. \u0641\u064a \u0634\u0639\u0631 \u062f\u0631\u0648\u064a\u0634 \u064a\u0645\u062a\u0632\u062c \u0627\u0644\u062d\u0628 \u0628\u0627\u0644\u0648\u0637\u0646 \u0648\u0628\u0627\u0644\u062d\u0628\u064a\u0628\u0629 \u0627\u0644\u0623\u0646\u062b\u0649. \u0642\u0627\u0645 \u0628\u0643\u062a\u0627\u0628\u0629 \u0648\u062b\u064a\u0642\u0629 \u0625\u0639\u0644\u0627\u0646 \u0627\u0644\u0627\u0633\u062a\u0642\u0644\u0627\u0644 \u0627\u0644\u0641\u0644\u0633\u0637\u064a\u0646\u064a \u0627\u0644\u062a\u064a \u062a\u0645 \u0625\u0639\u0644\u0627\u0646\u0647\u0627 \u0641\u064a \u0627\u0644\u062c\u0632\u0627\u0626\u0631. \u0645\u062d\u0645\u0648\u062f \u062f\u0631\u0648\u064a\u0634 \u0647\u0648 \u0634\u0627\u0639\u0631\u064c \u0641\u0644\u0633\u0637\u064a\u0646\u064a \u0648\u0639\u0636\u0648 \u0627\u0644\u0645\u062c\u0644\u0633 \u0627\u0644\u0648\u0637\u0646\u064a \u0627\u0644\u0641\u0644\u0633\u0637\u064a\u0646\u064a \u0627\u0644\u062a\u0627\u0628\u0639 \u0644\u0645\u0646\u0638\u0645\u0629 \u0627\u0644\u062a\u062d\u0631\u064a\u0631 \u0627\u0644\u0641\u0644\u0633\u0637\u064a\u0646\u064a\u0629\u060c \u0648\u0644\u0647 \u062f\u0648\u0627\u0648\u064a\u0646 \u0634\u0639\u0631\u064a\u0629 \u0645\u0644\u064a\u0626\u0629 \u0628\u0627\u0644\u0645\u0636\u0627\u0645\u064a\u0646 \u0627\u0644\u062d\u062f\u0627\u062b\u064a\u0629. \u0648\u0644\u062f \u0639\u0627\u0645 1941 \u0641\u064a \u0642\u0631\u064a\u0629 \u0627\u0644\u0628\u0631\u0648\u0629 \u0648\u0647\u064a \u0642\u0631\u064a\u0629 \u0641\u0644\u0633\u0637\u064a\u0646\u064a\u0629 \u062a\u0642\u0639 \u0641\u064a \u0627\u0644\u062c\u0644\u064a\u0644 \u0642\u0631\u0628 \u0633\u0627\u062d\u0644 \u0639\u0643\u0627\u060c \u062d\u064a\u062b \u0643\u0627\u0646\u062a \u0623\u0633\u0631\u062a\u0647 \u062a\u0645\u0644\u0643 \u0623\u0631\u0636\u064b\u0627 \u0647\u0646\u0627\u0643. \u062e\u0631\u062c\u062a \u0627\u0644\u0623\u0633\u0631\u0629 \u0628\u0631\u0641\u0642\u0629 \u0627\u0644\u0644\u0627\u062c\u0626\u064a\u0646 \u0627\u0644\u0641\u0644\u0633\u0637\u064a\u0646\u064a\u064a\u0646 \u0641\u064a \u0627\u0644\u0639\u0627\u0645 1948 \u0625\u0644\u0649 \u0644\u0628\u0646\u0627\u0646\u060c \u062b\u0645 \u0639\u0627\u062f\u062a \u0645\u062a\u0633\u0644\u0644\u0629 \u0639\u0627\u0645 1949 \u0628\u0639\u062f \u062a\u0648\u0642\u064a\u0639 \u0627\u062a\u0641\u0627\u0642\u064a\u0627\u062a \u0627\u0644\u0647\u062f\u0646\u0629\u060c \u0644\u062a\u062c\u062f \u0627\u0644\u0642\u0631\u064a\u0629 \u0645\u0647\u062f\u0645\u0629 \u0648\u0642\u062f \u0623\u0642\u064a\u0645 \u0639\u0644\u0649 \u0623\u0631\u0627\u0636\u064a\u0647\u0627 \u0645\u0648\u0634\u0627\u0641 (\u0642\u0631\u064a\u0629 \u0632\u0631\u0627\u0639\u064a\u0629 \u0625\u0633\u0631\u0627\u0626\u064a\u0644\u064a\u0629)\u00ab\u0623\u062d\u064a\u0647\u0648\u062f\u00bb. \u0648\u0643\u064a\u0628\u0648\u062a\u0633 \u064a\u0633\u0639\u0648\u0631 \u0641\u0639\u0627\u0634 \u0645\u0639 \u0639\u0627\u0626\u0644\u062a\u0647 \u0641\u064a \u0627\u0644\u0642\u0631\u064a\u0629 \u0627\u0644\u062c\u062f\u064a\u062f\u0629. \u0628\u0639\u062f \u0625\u0646\u0647\u0627\u0626\u0647 \u062a\u0639\u0644\u064a\u0645\u0647 \u0627\u0644\u062b\u0627\u0646\u0648\u064a \u0641\u064a \u0645\u062f\u0631\u0633\u0629 \u0628\u0646\u064a \u0627\u0644\u062b\u0627\u0646\u0648\u064a\u0629 \u0641\u064a \u0643\u0641\u0631\u064a\u0627\u0633\u064a\u0641 \u0627\u0646\u062a\u0633\u0628 \u0625\u0644\u0649 \u0627\u0644\u062d\u0632\u0628 \u0627\u0644\u0634\u064a\u0648\u0639\u064a \u0627\u0644\u0625\u0633\u0631\u0627\u0626\u064a\u0644\u064a \u0648\u0639\u0645\u0644 \u0641\u064a \u0635\u062d\u0627\u0641\u0629 \u0627\u0644\u062d\u0632\u0628  \u0645\u062b\u0644 \u0627\u0644\u0627\u062a\u062d\u0627\u062f \u0648\u0627\u0644\u062c\u062f\u064a\u062f \u0627\u0644\u062a\u064a \u0623\u0635\u0628\u062d \u0641\u064a \u0645\u0627 \u0628\u0639\u062f \u0645\u0634\u0631\u0641\u064b\u0627 \u0639\u0644\u0649 \u062a\u062d\u0631\u064a\u0631\u0647\u0627\u060c \u0643\u0645\u0627 \u0627\u0634\u062a\u0631\u0643 \u0641\u064a \u062a\u062d\u0631\u064a\u0631 \u062c\u0631\u064a\u062f\u0629 \u0627\u0644\u0641\u062c\u0631 \u0627\u0644\u062a\u064a \u0643\u0627\u0646 \u064a\u0635\u062f\u0631\u0647\u0627 \u0645\u0628\u0627\u0645. \u0baa\u0bbf\u0bb0\u0bc7\u0b9a\u0bbf\u0bb2\u0bcd (Brazil; ; ) \u0b85\u0bb2\u0bcd\u0bb2\u0ba4\u0bc1 \u0baa\u0bbf\u0bb0\u0bc7\u0b9a\u0bbf\u0bb2\u0bcd \u0b95\u0bc2\u0b9f\u0bcd\u0b9f\u0bbe\u0b9f\u0bcd\u0b9a\u0bbf\u0b95\u0bcd \u0b95\u0bc1\u0b9f\u0bbf\u0baf\u0bb0\u0b9a\u0bc1 (Federative Republic of Brazil, , ), \u0ba4\u0bc6\u0ba9\u0bcd \u0b85\u0bae\u0bc6\u0bb0\u0bbf\u0b95\u0bcd\u0b95\u0bbe\u0bb5\u0bbf\u0bb2\u0bcd \u0bae\u0bbf\u0b95\u0baa\u0bcd \u0baa\u0bc6\u0bb0\u0bbf\u0baf\u0ba4\u0bc1\u0bae\u0bcd \u0bae\u0bbf\u0b95\u0bc1\u0ba8\u0bcd\u0ba4 \u0bae\u0b95\u0bcd\u0b95\u0bb3\u0bcd \u0ba4\u0bca\u0b95\u0bc8 \u0b95\u0bca\u0ba3\u0bcd\u0b9f\u0ba4\u0bc1\u0bae\u0bbe\u0ba9 \u0ba8\u0bbe\u0b9f\u0bbe\u0b95\u0bc1\u0bae\u0bcd. \u0b87\u0ba4\u0bc1 \u0baa\u0bb0\u0baa\u0bcd\u0baa\u0bb3\u0bb5\u0bbf\u0ba9\u0bcd \u0b85\u0b9f\u0bbf\u0baa\u0bcd\u0baa\u0b9f\u0bc8\u0baf\u0bbf\u0bb2\u0bc1\u0bae\u0bcd, \u0bae\u0b95\u0bcd\u0b95\u0bb3\u0bcd\u0ba4\u0bca\u0b95\u0bc8 \u0b85\u0b9f\u0bbf\u0baa\u0bcd\u0baa\u0b9f\u0bc8\u0baf\u0bbf\u0bb2\u0bc1\u0bae\u0bcd \u0b89\u0bb2\u0b95\u0bbf\u0bb2\u0bc7\u0baf\u0bc7 \u0b90\u0ba8\u0bcd\u0ba4\u0bbe\u0bb5\u0ba4\u0bc1 \u0baa\u0bc6\u0bb0\u0bbf\u0baf \u0ba8\u0bbe\u0b9f\u0bc1 \u0b86\u0b95\u0bc1\u0bae\u0bcd. \u0b87\u0ba4\u0ba9\u0bcd \u0bae\u0b95\u0bcd\u0b95\u0bb3\u0bcd\u0ba4\u0bca\u0b95\u0bc8 192 \u0bae\u0bbf\u0bb2\u0bcd\u0bb2\u0bbf\u0baf\u0ba9\u0bc1\u0b95\u0bcd\u0b95\u0bc1\u0bae\u0bcd \u0bae\u0bc7\u0bb1\u0bcd\u0baa\u0b9f\u0bcd\u0b9f\u0ba4\u0bc1. \u0baa\u0bbf\u0bb0\u0bc7\u0b9a\u0bbf\u0bb2\u0bbf\u0ba9\u0bcd \u0b95\u0bbf\u0bb4\u0b95\u0bcd\u0b95\u0bbf\u0bb2\u0bc1\u0bae\u0bcd \u0bb5\u0b9f\u0b95\u0bbf\u0bb4\u0b95\u0bcd\u0b95\u0bbf\u0bb2\u0bc1\u0bae\u0bcd \u0b85\u0b9f\u0bcd\u0bb2\u0bbe\u0ba3\u0bcd\u0b9f\u0bbf\u0b95\u0bcd \u0baa\u0bc6\u0bb0\u0bc1\u0b99\u0bcd\u0b95\u0b9f\u0bb2\u0bcd \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bc1. 7,491 \u0b95\u0bbf.\u0bae\u0bc0. (4,655 \u0bae\u0bc8\u0bb2\u0bcd) \u0ba8\u0bc0\u0bb3\u0bae\u0bbe\u0ba9 \u0b95\u0b9f\u0bb1\u0bcd\u0b95\u0bb0\u0bc8 \u0baa\u0bbf\u0bb0\u0bc7\u0b9a\u0bbf\u0bb2\u0bc1\u0b95\u0bcd\u0b95\u0bc1 \u0b89\u0ba3\u0bcd\u0b9f\u0bc1. \u0baa\u0bbf\u0bb0\u0bc7\u0b9a\u0bbf\u0bb2\u0bbf\u0ba9\u0bcd \u0b85\u0bb0\u0bc1\u0b95\u0bbe\u0bae\u0bc8\u0baf\u0bbf\u0bb2\u0bcd \u0b89\u0bb0\u0bc1\u0b95\u0bc1\u0bb5\u0bc7, \u0b85\u0bb0\u0bcd\u0b9c\u0bc6\u0ba9\u0bcd\u0b9f\u0bbf\u0ba9\u0bbe, \u0baa\u0bb0\u0bbe\u0b95\u0bc1\u0bb5\u0bc7, \u0baa\u0bca\u0bb2\u0bbf\u0bb5\u0bbf\u0baf\u0bbe, \u0baa\u0bc6\u0bb0\u0bc1, \u0b95\u0bca\u0bb2\u0bae\u0bcd\u0baa\u0bbf\u0baf\u0bbe, \u0bb5\u0bc6\u0ba9\u0bbf\u0b9a\u0bc2\u0bb2\u0bbe, \u0b95\u0baf\u0bbe\u0ba9\u0bbe, \u0b9a\u0bc1\u0bb0\u0bbf\u0ba9\u0bbe\u0bae\u0bcd, \u0baa\u0bbf\u0bb0\u0bc6\u0b9e\u0bcd\u0b9a\u0bc1 \u0b95\u0baf\u0bbe\u0ba9\u0bbe \u0b86\u0b95\u0bbf\u0baf \u0ba8\u0bbe\u0b9f\u0bc1\u0b95\u0bb3\u0bcd \u0b89\u0bb3\u0bcd\u0bb3\u0ba9. \u0b85\u0ba4\u0bbe\u0bb5\u0ba4\u0bc1, \u0b8e\u0b95\u0bcd\u0b95\u0bc1\u0bb5 \u0baa\u0bcb\u0bb0\u0bcd\u0ba4\u0bcd\u0ba4\u0bc1\u0b95\u0bc0\u0b9a\u0bbf\u0baf\u0bb0\u0bbf\u0ba9\u0bcd \u0b86\u0b9f\u0bcd\u0b9a\u0bbf\u0baf\u0bbf\u0bb2\u0bcd \u0bae\u0bc1\u0ba9\u0bcd\u0baa\u0bc1 \u0b87\u0bb0\u0bc1\u0ba8\u0bcd\u0ba4\u0ba4\u0bbe\u0bb2\u0bcd \u0baa\u0bcb\u0bb0\u0bcd\u0ba4\u0bcd\u0ba4\u0bc1\u0b95\u0bc0\u0b9a \u0bae\u0bca\u0bb4\u0bbf \u0baa\u0bbf\u0bb0\u0bc7\u0b9a\u0bbf\u0bb2\u0bbf\u0bb2\u0bcd \u0baa\u0bc7\u0b9a\u0baa\u0bcd\u0baa\u0b9f\u0bc1\u0bae\u0bcd \u0bae\u0bca\u0bb4\u0bbf\u0baf\u0bc1\u0bae\u0bcd, \u0b85\u0ba4\u0bbf\u0b95\u0bbe\u0bb0\u0baa\u0bcd\u0baa\u0bc2\u0bb0\u0bcd\u0bb5 \u0bae\u0bca\u0bb4\u0bbf\u0baf\u0bc1\u0bae\u0bcd \u0b86\u0b95\u0bc1\u0bae\u0bcd. \u0ba4\u0bc6\u0ba9\u0bcd\u0ba9\u0bae\u0bc6\u0bb0\u0bbf\u0b95\u0bcd\u0b95\u0bbe\u0bb5\u0bbf\u0bb2\u0bcd \u0baa\u0bc6\u0bb0\u0bc1\u0bae\u0bcd\u0baa\u0bbe\u0ba9\u0bcd\u0bae\u0bc8\u0baf\u0bbe\u0b95\u0baa\u0bcd \u0baa\u0bcb\u0ba4\u0bcd\u0ba4\u0bc1\u0b95\u0bcd\u0b95\u0bc0\u0b9a \u0bae\u0bca\u0bb4\u0bbf\u0baf\u0bc8\u0baa\u0bcd \u0baa\u0bc7\u0b9a\u0bc1\u0baa\u0bb5\u0bb0\u0bcd\u0b95\u0bb3\u0bc8\u0b95\u0bcd \u0b95\u0bca\u0ba3\u0bcd\u0b9f \u0ba8\u0bbe\u0b9f\u0bc1 \u0b87\u0ba4\u0bc1 \u0bae\u0b9f\u0bcd\u0b9f\u0bc1\u0bae\u0bc7. \u0b85\u0ba4\u0bcd\u0ba4\u0bc1\u0b9f\u0ba9\u0bcd, \u0b87\u0bae\u0bcd\u0bae\u0bca\u0bb4\u0bbf\u0baf\u0bc8\u0baa\u0bcd \u0baa\u0bc7\u0b9a\u0bc1\u0b95\u0bbf\u0ba9\u0bcd\u0bb1 \u0b89\u0bb2\u0b95\u0bbf\u0ba9\u0bcd \u0bae\u0bbf\u0b95\u0baa\u0bcd \u0baa\u0bc6\u0bb0\u0bbf\u0baf \u0ba8\u0bbe\u0b9f\u0bc1\u0bae\u0bcd \u0b87\u0ba4\u0bc1\u0bb5\u0bc7. 1500 \u0b86\u0bae\u0bcd \u0b86\u0ba3\u0bcd\u0b9f\u0bbf\u0bb2\u0bcd \u0baa\u0bc6\u0b9f\u0bcd\u0bb0\u0bcb \u0b86\u0bb2\u0bcd\u0bb5\u0bbe\u0bb0\u0bc6\u0b9a\u0bc1 \u0b95\u0bbe\u0baa\u0bcd\u0bb0\u0bbe\u0bb2\u0bcd \u0b95\u0bbe\u0bb2\u0bcd \u0bb5\u0bc8\u0ba4\u0bcd\u0ba4\u0ba4\u0bbf\u0bb2\u0bbf\u0bb0\u0bc1\u0ba8\u0bcd\u0ba4\u0bc1 1815 \u0b86\u0bae\u0bcd \u0b86\u0ba3\u0bcd\u0b9f\u0bc1\u0bb5\u0bb0\u0bc8 \u0baa\u0bbf\u0bb0\u0bc7\u0b9a\u0bbf\u0bb2\u0bcd \u0baa\u0bcb\u0bb0\u0bcd\u0ba4\u0bcd\u0ba4\u0bc1\u0b95\u0bcd\u0b95\u0bb2\u0bbf\u0ba9\u0bcd \u0b95\u0bc1\u0b9f\u0bbf\u0baf\u0bc7\u0bb1\u0bcd\u0bb1 \u0ba8\u0bbe\u0b9f\u0bbe\u0b95 \u0b87\u0bb0\u0bc1\u0ba8\u0bcd\u0ba4\u0ba4\u0bc1. 1815\u0bb2\u0bcd \u0baa\u0bbf\u0bb0\u0bc7\u0b9a\u0bbf\u0bb2\u0bcd \u0b92\u0bb0\u0bc1 \u0b87\u0bb0\u0bbe\u0b9a\u0bcd\u0b9a\u0bbf\u0baf\u0bae\u0bbe\u0b95\u0ba4\u0bcd \u0ba4\u0bb0\u0bae\u0bcd \u0b89\u0baf\u0bb0\u0bcd\u0ba4\u0bcd\u0ba4\u0baa\u0bcd\u0baa\u0b9f\u0bcd\u0b9f\u0bc1, \u0baa\u0bcb\u0bb0\u0bcd\u0ba4\u0bcd\u0ba4\u0bc1\u0b95\u0bcd\u0b95\u0bb2\u0bcd, \u0baa\u0bbf\u0bb0\u0bc7\u0b9a\u0bbf\u0bb2\u0bcd, \u0b85\u0bb2\u0bcd\u0b95\u0bbe\u0bb0\u0bcd\u0bb5\u0bc6\u0b9a\u0bc1 \u0b86\u0b95\u0bbf\u0baf\u0bb5\u0bb1\u0bcd\u0bb1\u0bbf\u0ba9\u0bcd \u0b90\u0b95\u0bcd\u0b95\u0bbf\u0baf \u0b87\u0bb0\u0bbe\u0b9a\u0bcd\u0b9a\u0bbf\u0baf\u0bae\u0bcd \u0b8e\u0ba9\u0bcd\u0ba9\u0bc1\u0bae\u0bcd \u0b85\u0bae\u0bc8\u0baa\u0bcd\u0baa\u0bc1 \u0b89\u0bb0\u0bc1\u0bb5\u0bbe\u0b95\u0bcd\u0b95\u0baa\u0bcd\u0baa\u0b9f\u0bcd\u0b9f\u0ba4\u0bc1. \u0b89\u0ba3\u0bcd\u0bae\u0bc8\u0baf\u0bbf\u0bb2\u0bcd, 1808 \u0b86\u0bae\u0bcd \u0b86\u0ba3\u0bcd\u0b9f\u0bbf\u0bb2\u0bcd \u0ba8\u0bc6\u0baa\u0bcd\u0baa\u0bcb\u0bb2\u0bbf\u0baf\u0ba9\u0bcd \u0baa\u0bcb\u0bb0\u0bcd\u0ba4\u0bcd\u0ba4\u0bc1\u0b95\u0bcd\u0b95\u0bb2\u0bc8\u0b95\u0bcd \u0b95\u0bc8\u0baa\u0bcd\u0baa\u0bb1\u0bcd\u0bb1\u0bbf\u0b95\u0bcd\u0b95\u0bca\u0ba3\u0bcd\u0b9f\u0baa\u0bcb\u0ba4\u0bc1, \u0baa\u0bcb\u0bb0\u0bcd\u0ba4\u0bcd\u0ba4\u0bc1\u0b95\u0bcd\u0b95\u0bc0\u0b9a\u0b95\u0bcd \u0b95\u0bc1\u0b9f\u0bbf\u0baf\u0bc7\u0bb1\u0bcd\u0bb1\u0bb5\u0bbe\u0ba4\u0baa\u0bcd \u0baa\u0bc7\u0bb0\u0bb0\u0b9a\u0bbf\u0ba9\u0bcd \u0ba4\u0bb2\u0bc8\u0ba8\u0b95\u0bb0\u0bae\u0bcd \u0bb2\u0bbf\u0b9a\u0bc1\u0baa\u0bcd\u0baa\u0ba9\u0bbf\u0bb2\u0bbf\u0bb0\u0bc1\u0ba8\u0bcd\u0ba4\u0bc1 \u0b87\u0bb0\u0bbf\u0baf\u0bcb \u0b9f\u0bbf \u0b9a\u0bc6\u0ba9\u0bc0\u0bb0\u0bcb\u0bb5\u0bc1\u0b95\u0bcd\u0b95\u0bc1 \u0bae\u0bbe\u0bb1\u0bcd\u0bb1\u0baa\u0bcd\u0baa\u0b9f\u0bcd\u0b9f\u0baa\u0bcb\u0ba4\u0bc1 \u0b95\u0bc1\u0b9f\u0bbf\u0baf\u0bc7\u0bb1\u0bcd\u0bb1\u0bb5\u0bbe\u0ba4\u0baa\u0bcd \u0baa\u0bbf\u0ba3\u0bc8\u0baa\u0bcd\u0baa\u0bc1 \u0b85\u0bb1\u0bc1\u0ba8\u0bcd\u0ba4\u0bc1\u0bb5\u0bbf\u0b9f\u0bcd\u0b9f\u0ba4\u0bc1. \u041a\u043e\u043d\u0440\u0430\u0434 \u0411\u043e\u0442\u043e \u0432 \u0441\u0432\u043e\u0435\u0439 \u00ab\u0421\u0430\u043a\u0441\u043e\u043d\u0441\u043a\u043e\u0439 \u0445\u0440\u043e\u043d\u0438\u043a\u0435\u00bb (Chronecken der Sassen, 1492) \u0443\u043f\u043e\u043c\u0438\u043d\u0430\u0435\u0442 \u0441\u043b\u0430\u0432\u044f\u043d\u0441\u043a\u043e\u0433\u043e \u0431\u043e\u0433\u0430 \u041a\u0440\u043e\u0434\u043e (Crodo) \u0438\u043b\u0438 \u0421\u0430\u0442\u0430\u0440\u0430, \u0430\u043b\u0442\u0430\u0440\u044c \u043a\u043e\u0442\u043e\u0440\u043e\u0433\u043e \u0438\u043c\u0435\u043b\u0441\u044f \u0432 \u0413\u043e\u0441\u043b\u0430\u0440\u0435 \u0438 \u0447\u044c\u0451 \u0438\u043c\u044f \u043d\u043e\u0441\u0438\u043b \u0441\u043e\u043b\u044f\u043d\u043e\u0439 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u0432\u043e\u0437\u043b\u0435 \u0411\u0430\u0434-\u0413\u0430\u0440\u0446\u0431\u0443\u0440\u0433\u0430. \u0412\u043e\u0437\u043c\u043e\u0436\u043d\u043e, \u0447\u0442\u043e \u0438\u043c\u044f \u041a\u0440\u043e\u0434\u043e \u043e\u0431\u0440\u0430\u0437\u043e\u0432\u0430\u043d\u043e \u043e\u0442 \u041a\u0440\u043e\u043d\u043e\u0441, \u0430 \u0421\u0430\u0442\u0430\u0440\u00a0\u2014 \u0438\u0437 \u0421\u0430\u0442\u0443\u0440\u043d. \u0412 \u0413\u043e\u0441\u043b\u0430\u0440\u0441\u043a\u043e\u043c \u043c\u0443\u0437\u0435\u0435 \u044d\u043a\u0441\u043f\u043e\u043d\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0442\u0430\u043a \u043d\u0430\u0437\u044b\u0432\u0430\u0435\u043c\u044b\u0439 \u00ab\u0430\u043b\u0442\u0430\u0440\u044c \u041a\u0440\u043e\u0434\u043e\u00bb\u00a0\u2014 \u043a\u0430\u0442\u043e\u043b\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0430\u043b\u0442\u0430\u0440\u044c \u043a\u043e\u043d\u0446\u0430 XII \u0432\u0435\u043a\u0430 \u0438\u0437 \u043a\u0430\u0444\u0435\u0434\u0440\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0441\u043e\u0431\u043e\u0440\u0430 \u0433\u043e\u0440\u043e\u0434\u0430. \u0421\u043e\u0433\u043b\u0430\u0441\u043d\u043e \u043f\u043e\u0437\u0434\u043d\u0435\u0439 \u043b\u0435\u0433\u0435\u043d\u0434\u0435 \u043d\u0430\u0447\u0430\u043b\u0430 XVIII \u0432\u0435\u043a\u0430, \u044d\u0442\u043e\u0442 \u0430\u043b\u0442\u0430\u0440\u044c \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043b\u0441\u044f \u0432 \u0445\u0440\u0430\u043c\u0435 \u041a\u0440\u043e\u0434\u043e. \u0412 \u0423\u0440\u0430-\u041b\u0438\u043d\u0434\u0430, \u043f\u043e\u0434\u043b\u043e\u0436\u043d\u043e\u0439 \u0445\u0440\u043e\u043d\u0438\u043a\u0435 \u0434\u0440\u0435\u0432\u043d\u0438\u0445 \u0444\u0440\u0438\u0437\u043e\u0432, \u043d\u0430 \u0441. 45 \u043d\u0430\u0440\u0438\u0441\u043e\u0432\u0430\u043d\u044b \u0442\u0440\u0438 \u043a\u043e\u043b\u0435\u0441\u0430 \u0441 \u0448\u0435\u0441\u0442\u044c\u044e \u0441\u043f\u0438\u0446\u0430\u043c\u0438, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043f\u043e\u0434\u043f\u0438\u0441\u0430\u043d\u044b \u043a\u0430\u043a \u0412\u0440\u0430\u043b\u044c\u0434\u0430, \u0418\u0441\u0442\u043e\u043a \u0438 \u041d\u0430\u0447\u0430\u043b\u043e, \u0430 \u0432 \u0442\u0435\u043a\u0441\u0442\u0435 \u0441\u043b\u0435\u0434\u0443\u0435\u0442 \u043f\u043e\u044f\u0441\u043d\u0435\u043d\u0438\u0435 \u00ab\u042d\u0442\u043e\u00a0\u2014 \u043a\u0440\u043e\u0434\u0435\u0440, \u043a\u043e\u043b\u0435\u0441\u043e, \u0432\u0435\u0447\u043d\u043e \u0432\u0440\u0430\u0449\u0430\u044e\u0449\u0435\u0435\u0441\u044f \u0432\u043c\u0435\u0441\u0442\u0435 \u0441 \u042e\u043b\u043e\u043c\u00bb.", length: 512, sameAsFull: true,
